elss =  """Equity Linked Savings Scheme (ELSS) is a tax-saving mutual fund that invests primarily in equities. It comes with a 3-year lock-in period and qualifies for tax deduction under Section 80C of the Income Tax Act.""",
small_cap =  """Small Cap funds invest in companies with small market capitalization (below top 250 listed companies). These funds have high growth potential but are also highly volatile and risky.""",
mid_cap =  """Mid Cap funds invest in medium-sized companies (ranked 101–250 by market cap). They offer a balance between risk and return, with better growth potential than large caps and less volatility than small caps.""",
sectoral_thematic =  """Sectoral/Thematic funds invest in specific sectors (like pharma, IT, infrastructure) or themes (like ESG, digital India). These funds can generate high returns when the theme performs well but are high-risk and cyclical.""",
index =  """Index funds aim to replicate the performance of a specific stock market index like Nifty 50 or Sensex. They are passively managed and have lower expense ratios but provide market-average returns.""",
large_cap =  """Large Cap funds invest in top 100 companies by market capitalization. These companies are financially stable and offer consistent but moderate returns with lower risk.""",
contra =  """Contra funds follow a contrarian investment strategy — buying underperforming stocks expected to recover. These require a long-term view and involve relatively higher risk.""",
dynamic_asset_allocation =  """Dynamic Asset Allocation or Balanced Advantage Funds automatically adjust the ratio between equity and debt based on market conditions, aiming to reduce volatility and optimize returns.""",
aggressive_hybrid =  """Aggressive Hybrid Funds invest 65–80% in equities and the rest in debt instruments. They offer higher return potential than conservative hybrids, with relatively higher risk.""",
multi_cap =  """Multi Cap funds invest across large, mid, and small cap stocks with a minimum of 25% in each category. They offer diversified exposure to all market segments.""",
large_midcap =  """Large & Mid Cap funds invest at least 35% each in large-cap and mid-cap companies, offering a blend of stability and growth potential.""",
fof_overseas_domestic =  """Fund of Funds (FoF) invest in other mutual fund schemes, either domestic or international. They allow diversification across strategies or geographies but have double-layered costs.""",
flexi_cap =  """Flexi Cap funds invest across large, mid, and small caps without any fixed allocation. Fund managers have the flexibility to shift between segments based on market outlook.""",
multi_asset_allocation =  """These funds invest in at least three asset classes — typically equity, debt, and gold — with at least 10% in each. They aim to provide diversification and reduce overall portfolio risk.""",
liquid =  """Liquid funds invest in very short-term debt instruments (up to 91 days). They are ideal for parking surplus money with high liquidity and better returns than savings accounts.""",
value =  """Value funds follow value investing strategy — identifying fundamentally strong stocks trading below their intrinsic value. These are for long-term investors with patience for market revaluation.""",
retirement =  """Retirement funds are long-term mutual fund schemes designed to help accumulate corpus for retirement. They may come with lock-in periods and asset allocation based on age/goal.""",
overnight =  """Overnight funds invest in debt and money market instruments with a one-day maturity. They offer lowest credit and interest rate risk, ideal for very short-term parking of funds.""",
dividend_yield =  """Dividend Yield funds focus on stocks that pay high dividends consistently. These funds suit conservative investors seeking steady income and potential capital appreciation.""",
focused =  """Focused funds invest in a concentrated portfolio of up to 30 stocks. The limited number of holdings can generate high returns but increases concentration risk.""",
conservative_hybrid =  """Conservative Hybrid Funds invest 75–90% in debt and the rest in equity. They aim for stability and regular income with modest capital appreciation.""",
short_duration =  """Short Duration funds invest in debt instruments with Macaulay duration of 1 to 3 years. Suitable for short-term investors seeking better returns than fixed deposits with moderate risk.""",
medium_duration =  """Medium Duration funds invest in debt instruments with Macaulay duration of 3 to 4 years. They balance return and risk for investors with a medium-term horizon.""",
banking_and_psu =  """These funds invest at least 80% in debt instruments of banks, public sector undertakings (PSUs), and public financial institutions. Considered low-risk and relatively stable.""",
arbitrage =  """Arbitrage funds take advantage of price differences between cash and derivatives markets. Returns are modest but relatively safe and tax-efficient in short term.""",
ultra_short_duration =  """Ultra Short Duration funds invest in instruments with maturity of 3–6 months. They offer slightly higher returns than liquid funds, with limited volatility.""",
gilt =  """Gilt funds invest only in government securities. They have zero credit risk but are sensitive to interest rate movements, hence suitable for risk-averse investors with interest rate view.""",
equity_savings =  """Equity Savings funds use a mix of equity, arbitrage, and debt strategies. They aim to provide stable returns with lower volatility and equity taxation benefits.""",
corporate_bond =  """Corporate Bond funds invest at least 80% in highest-rated corporate bonds. They aim to offer better returns than government securities with moderate credit risk.""",
long_duration =  """Long Duration funds invest in debt instruments with a Macaulay duration of over 7 years. They can be volatile but offer high returns if interest rates fall.""",
dynamic_bond =  """Dynamic Bond funds actively manage duration based on interest rate outlook. Suitable for investors who want professional handling of interest rate risk.""",
money_market =  """Money Market funds invest in money market instruments with maturity up to 1 year. They aim to provide liquidity and safety for short-term investments.""",
credit_risk =  """Credit Risk funds invest at least 65% in lower-rated corporate bonds. They offer higher returns but come with increased credit/default risk.""",
children =  """Children's funds are goal-based mutual funds designed to build a corpus for children's future needs, often with lock-in and conservative-to-moderate asset allocation.""",
gilt_10_year =  """Gilt 10-Year funds invest in government securities with 10-year maturity. Suitable for investors with long-term goals and view on interest rates.""",
fmp =  """Fixed Maturity Plans (FMPs) are close-ended debt funds that invest in fixed-income securities maturing on or before the scheme’s maturity date. Returns are more predictable but not guaranteed.""",
low_duration =  """Low Duration funds invest in instruments with maturity of 6 to 12 months. Suitable for investors looking for slightly higher returns than savings or liquid funds with low risk.""",
balanced_hybrid =  """Balanced Hybrid funds invest 40–60% in equities and the rest in debt. They aim to provide balanced risk-return for moderate investors.""",
medium_to_long_duration =  """These funds invest in debt instruments with Macaulay duration of 4–7 years. Suitable for investors with a longer horizon and moderate interest rate risk tolerance.""",
floater =  """Floater funds invest in debt instruments with floating interest rates. They benefit from rising interest rate environments and carry low duration risk."""